{
  "case_id": "xsu_sg_010_congenital_impairment_documentation",
  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "met",
      "reason": "Svaret gengiver kernen korrekt: sygehistorie, seneste journalnotater, epikriser, udrednings- og behandlingsforløb, aktuelle symptomer, støtteafgørelser og personlig redegørelse. Det fastholder det lægefaglige minimum (§ 37, stk. 3) og siger, at redegørelsen kun er et supplement. Svaret fremstiller ikke ny dokumentation som ubetinget krav og gør ikke eksemplerne obligatoriske. Der er ingen væsentlig juridisk fejl."
    },
    "c02_required_elements_complete": {
      "label": "met",
      "reason": "Alle fire kritiske elementer er med: sygehistorik og seneste journalnotater, udrednings- og behandlingsforløb samt aktuelle symptomer, epikriser og journalnotater sammen med støtteforanstaltninger som supplement, og den personlige redegørelse."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret handler direkte om, hvilken dokumentation en ansøger med medfødt funktionsnedsættelse kan sende med. Afsnittet om minimumskrav er relevant som ramme."
    },
    "c04_source_traceability": {
      "label": "met",
      "reason": "Svaret henviser til SU-bekendtgørelsen (bekendtgørelse nr. 841 af 2026) og vejledning nr. 10157 af 5. oktober 2026 via nummererede henvisninger og en kildeliste. Væsentlige udsagn kan føres tilbage til disse kilder."
    },
    "c05_source_validity": {
      "label": "met",
      "reason": "De angivne kilder er SU-bekendtgørelsen nr. 841 af 2026 og vejledning nr. 10157 af 2026. Begge findes i det frosne materiale og er autoritative og aktuelle."
    },
    "c06_claim_source_support": {
      "label": "not_met",
      "reason": "Det meste støttes af vejledningens afsnit 4.3 og bekendtgørelsens § 37. To udsagn går videre end kilderne: (1) \"Hvis dokumentationen er for sparsom, kan ansøgningen blive afvist uden realitetsbehandling\". Det står ikke i de udleverede passager, og § 37, stk. 5 om frist for yderligere dokumentation peger i en anden retning. (2) Det praktiske svar nævner en \"lægefaglig beskrivelse af diagnosen og varigheden\". Det svarer kun delvist til passagen i afsnit 4.3, men er dækket af § 37, stk. 1."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "not_met",
      "reason": "Svaret tilføjer en retsvirkning uden støtte i materialet: at en ansøgning kan afvises uden realitetsbehandling, hvis dokumentationen er for sparsom. De udleverede kilder nævner i stedet muligheden for at fastsætte en frist for yderligere dokumentation (§ 37, stk. 5)."
    },
    "c08_qualifications_and_exceptions": {
      "label": "met",
      "reason": "Svaret bevarer de vigtige forbehold. Redegørelsen er et supplement, hvor lægefaglig dokumentation ikke findes eller er utilstrækkelig. Der kan mangle nyere dokumentation, og det lægefaglige minimum gælder fortsat. Eksemplerne fremstår som ikke-kumulative med formuleringer som \"især\" og \"typisk relevant\". Svaret nævner ikke udtrykkeligt, at eksemplerne ikke er udtømmende, men det er kun et støtteelement."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Opbygningen er sammenhængende: først minimumskravet, derefter eksempler på dokumentation, og til sidst særligt om medfødte funktionsnedsættelser. Konklusionen følger af trinnene."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger mest præcise modalverber som \"kan\", \"typisk\" og \"især\". Der er dog to afvigelser. Åbningen \"skal som minimum vedlægge\" er korrekt efter § 37, men \"dokumentationen skal være aktuel\" gengives uden at nævne, at vejledningen accepterer de seneste foreliggende oplysninger, som kan være ældre. Desuden gør \"kan ansøgningen blive afvist uden realitetsbehandling\" en ikke-understøttet konsekvens til en mulig retsfølge."
    }
  },
  "xhaile_coverage": {
    "A49": {
      "label": "yes",
      "reason": "Svaret dækker afsnit 4.3 om medfødt funktionsnedsættelse: sygehistorik, seneste journalnotater, manglende nyere dokumentation og den personlige redegørelse. Det gengiver ikke den ikke-udtømmende liste over diagnoser, men det er ikke afgørende for spørgsmålet."
    },
    "A35": {
      "label": "yes",
      "reason": "Svaret dækker de alternative og supplerende dokumentationsformer: epikriser, journalnotater, støtteafgørelser, støtteforanstaltninger på tidligere uddannelser eller arbejdspladser, og personlig redegørelse hvor dokumentation mangler."
    }
  },
  "overall_notes": "Indholdet er stærkt og dækker rubrikkens kritiske elementer. Der er kildehenvisninger, og de angivne kilder er gyldige. Svaret har dog en tilføjelse uden støtte: afvisning uden realitetsbehandling ved sparsom dokumentation. Den gør, at C06, C07 og C10 ikke er opfyldt."
}

